package main

import (
	"fmt"
	"sync"
)

type Counter struct {
	mu sync.Mutex // guards n; never copy a Counter after use
	n  int
}

func (c *Counter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock() // released even if something panics
	c.n++               // critical section: the only place n is mutated
}

func (c *Counter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.n
}

func main() {
	var c Counter
	var wg sync.WaitGroup
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.Inc()
		}()
	}
	wg.Wait()
	fmt.Println("count:", c.Value())
}

package main

import (
	"fmt"
	"sync"
)

type Config struct {
	mu sync.RWMutex
	m  map[string]string
}

func NewConfig() *Config { return &Config{m: make(map[string]string)} }

func (c *Config) Get(k string) (string, bool) {
	c.mu.RLock()         // many readers may hold this at once
	defer c.mu.RUnlock()
	v, ok := c.m[k]
	return v, ok
}

func (c *Config) Set(k, v string) {
	c.mu.Lock()          // exclusive: blocks all readers and writers
	defer c.mu.Unlock()
	c.m[k] = v
}

func main() {
	c := NewConfig()
	var wg sync.WaitGroup

	c.Set("region", "us-east-1") // write before concurrent reads

	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if v, ok := c.Get("region"); ok {
				_ = v // each reader sees a consistent value
			}
		}()
	}
	wg.Wait()

	v, _ := c.Get("region")
	fmt.Println("region:", v)
}
